package in.finseq.insurance;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import org.json.*;

public class ActiveSessionsActivity extends FinseqActivity {
 LinearLayout root,body,list;
 @Override public void onCreate(Bundle b){super.onCreate(b);render();load();}
 void render(){root=Ui.column(this);Ui.appHeader(root,this,"Logged-in Devices");body=Ui.contentColumn(this);root.addView(body);body.addView(Ui.sub(this,"See active Android sessions. You can revoke another device without changing its local App Lock setting."));Button others=Ui.outlineButton(this,"Logout All Other Devices");body.addView(others);others.setOnClickListener(v->confirmOthers());list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);body.addView(list);setContentView(Ui.scroll(this,root));}
 void load(){list.removeAllViews();list.addView(Ui.sub(this,"Loading sessions…"));Ui.run(this,()->{try{JSONObject r=ApiClient.get(this,"/api/v1/sessions");Ui.ui(this,()->show(r.optJSONArray("sessions")));}catch(Exception e){Ui.ui(this,()->{list.removeAllViews();list.addView(Ui.sub(this,"Sessions unavailable: "+e.getMessage()));});}});}
 void show(JSONArray rows){list.removeAllViews();if(rows==null||rows.length()==0){list.addView(Ui.sub(this,"No active mobile sessions."));return;}for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);if(r==null)continue;LinearLayout c=Ui.card(this);String who=r.optString("user_name");String title=(who.isEmpty()?"":who+" · ")+r.optString("device_name","Android");if(r.optBoolean("current"))title+=" · THIS DEVICE";c.addView(Ui.text(this,title,17,true));c.addView(Ui.sub(this,"App "+r.optString("app_version","—")+" · Android "+r.optString("android_version","—")));c.addView(Ui.sub(this,"Last active: "+r.optString("last_seen_at","—")+" · IP: "+r.optString("last_ip","—")));c.addView(Ui.badge(this,r.optString("status","Active"),"Active".equals(r.optString("status"))?Ui.GREEN:Ui.RED));if(!r.optBoolean("current")&&"Active".equals(r.optString("status"))){Button revoke=Ui.outlineButton(this,"Force Logout This Device");String id=r.optString("session_id");revoke.setOnClickListener(v->confirmRevoke(id,title));c.addView(revoke);}list.addView(c);}}
 void confirmRevoke(String id,String label){new AlertDialog.Builder(this).setTitle("Force logout?").setMessage(label+" will be signed out on its next server request.").setNegativeButton("Cancel",null).setPositiveButton("Force Logout",(d,w)->post("/api/v1/sessions/"+id+"/revoke")).show();}
 void confirmOthers(){new AlertDialog.Builder(this).setTitle("Logout other devices?").setMessage("Your current phone stays signed in. All other FINSEQ mobile sessions for your user will be revoked.").setNegativeButton("Cancel",null).setPositiveButton("Logout Others",(d,w)->post("/api/v1/sessions/logout-others")).show();}
 void post(String path){Ui.run(this,()->{try{ApiClient.post(this,path,new JSONObject());Ui.ui(this,()->{Ui.toast(this,"Session updated");load();});}catch(Exception e){Ui.ui(this,()->Ui.toast(this,e.getMessage()));}});}
}
